INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Childcare low-pay warning as ministers meet operators in Fingal', 'childcare-low-pay-warning-as-ministers-meet-operators-in-fingal', '<p>A recent survey of more than 3,000 childcare managers and staff “indicated that many facilities face reducing services or potential closure over the coming months due to an inability to recruit the necessary qualified professionals required to run them,” said SIPTU.</p>
<p>SIPTU Head of Organising, Darragh O’Connor said: “Many qualified and skilled educators simply cannot afford to stay in their profession. The survey found that 42% of Early Years educators are actively looking for a job outside the sector with 75% identifying low pay as the reason for leaving their profession.</p>
<figure aria-describedby="caption-attachment-251081"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-1024x683.jpeg" alt="" width="1024" height="683" srcset="https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-1024x683.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-300x200.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-768x512.jpeg 768w, https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-1536x1024.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-2048x1365.jpeg 2048w, https://changingireland.ie/wp-content/uploads/2021/09/SIPTUs-Darragh-OConnor-1080x720.jpeg 1080w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>SIPTU&#8217;s Darragh O&#8217;Connor</figcaption></figure>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>&nbsp;</p>
<p>The Early Years Staffing Survey Report 2021 was launched at a special online briefing for Oireachtas members and reveals a sector “drifting further into crisis due to the impact of low pay and staff leaving the sector”.</p>
<p>Campaigners are calling on the Government to invest an additional €150m in childcare, split between pay and affordability measures.</p>
<p>Read more about the survey findings here: <a href="https://www.siptu.ie/media/pressreleases2019/mainnews/fullstory_22248_en.html">https://www.siptu.ie/media/pressreleases2019/mainnews/fullstory_22248_en.html</a></p>
<p>In February 2020, SIPTU’s childcare facilities campaign saw 30,000 people march in Dublin over low pay and lack of state investment.*</p>
<p><strong>FINGAL: Reps meet ministers</strong></p>
<p>Meanwhile, Children’s minister Roderic O’Gorman and Minister of State for Community Development, Joe O’Brien, met online with community representatives from Fingal on Sept. 10 “to discuss early years and childcare” issues in the local area.</p>
<figure aria-describedby="caption-attachment-251080"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-1024x597.jpeg" alt="" width="1024" height="597" srcset="https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-1024x597.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-300x175.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-768x448.jpeg 768w, https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-1536x896.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien-1080x630.jpeg 1080w, https://changingireland.ie/wp-content/uploads/2021/09/The-Fingal-area-childcare-meeting-was-attended-by-Ministers-OGorman-and-OBrien.jpeg 1563w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>The Fingal area childcare meeting was attended by Ministers O&#8217;Gorman and O&#8217;Brien</figcaption></figure>
<p>The Fingal Children and Young People’s Services Committee welcomed the meeting, saying: “Community based not for profit childcare services provide such essential services to communities.”</p>
<p>Grainne McKenna, who lectures in early childhood education at DCU, said it was “great to see engagement and discussion about the important and much valued work of community based early childhood settings in Fingal.”</p>
<p>Minister O’Brien remarked afterwards, “Good first meeting. Having affordable childcare for disadvantaged and marginalised communities is particularly important in facilitating community engagement and ultimately community development.”</p>
<p>Minister O’Gorman remarked, “These engagements are incredibly valuable in exploring solutions for communities in Fingal &amp; nationally.”</p>
<p>Empower Fingal organised the meeting.</p>
<p><a href="https://changingireland.ie/wp-content/uploads/2020/03/Issue-68-28p-Spring-2020-pubd-Fri-March-13.pdf" target="_blank" rel="noopener"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER-214x300.png" alt="" width="214" height="300" srcset="https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER-214x300.png 214w, https://changingireland.ie/wp-content/uploads/2020/03/ISS-68-SPRING-2020-COVER.png 634w" sizes="(max-width: 214px) 100vw, 214px" /></a></p>
<p>* <em>Read why 30,000 people marched in Dublin last year (just before Covid) here:</em> <a href="https://changingireland.ie/wp-content/uploads/2020/03/Issue-68-28p-Spring-2020-pubd-Fri-March-13.pdf">https://changingireland.ie/digital-magazine-archive/</a></p>
<p>&nbsp;</p>', 'Warning of a looming “winter of discontent” in the Community Sector, SIPTU has highlighted the plight of the community-based childcare services.', 'https://changingireland.ie/wp-content/uploads/2021/09/PHOTO-2021-09-21-16-56-31-2.jpg', '', '[{"slug":"community","title":"Community"},{"slug":"equality-rights","title":"Equality & Rights"}]', '[{"slug":"childcare","title":"childcare"},{"slug":"rights","title":"Rights"},{"slug":"siptu","title":"siptu"}]', '', 251079, 1, '2021-09-20T15:09:40Z', '2021-09-22T16:27:02Z', '2021-09-20T15:09:40Z')
