INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€1m social enterprise capital grants scheme', 'e1m-social-enterprise-capital-grants-scheme', '<p>The Social Enterprise Capital Grants Scheme 2021 provides funding for the purchase of equipment or the carrying out of repairs or refurbishments to enable social enterprises to improve their service delivery.</p>
<p>The Minister said, “This initiative builds on other successful schemes for social enterprises funded by my Department in recent years, such as the Training and Mentoring Scheme, the Small Capital Grants Scheme for Social Enterprises, and the Social Enterprise COVID-19 Regeneration Programme.</p>
<p>“This announcement underscores my commitment under the National Social Enterprise Policy to growing and strengthening Social Enterprise,” she said.</p>
<p>The scheme will be delivered by Local Community Development Committees (LCDCs). Final decisions on funding will be made by the Department of Rural and Community Development.”</p>
<p>To allow flexibility, the Department is not setting a national closing date, but will allow each LCDC to set its own, to best suit its area (but no later than 15 October 2021).</p>
<p><span>• </span>This new capital grants scheme supports one of the key commitments in the National Social Enterprise Policy for Ireland 2019-2022 – “Growing and Strengthening Social Enterprise”.</p>
<blockquote><p><a href="https://changingireland.ie/national-social-enterprise-policy-for-ireland-welcomed/">Ireland’s first national social enterprise policy welcomed by sector</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Ireland’s first national social enterprise policy welcomed by sector” — Changing Ireland" src="https://changingireland.ie/national-social-enterprise-policy-for-ireland-welcomed/embed/#?secret=Oa4Kkqi2pY#?secret=XVnEnvfv84" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'A new one million euro funding for social enterprises nationwide was announced on September 6th by Minister for Rural and Community Development, Heather Humphreys.', 'https://changingireland.ie/wp-content/uploads/2021/09/Dunhill-Ecopark-cafe.jpeg', '', '[{"slug":"enterprise","title":"Enterprise"}]', '[{"slug":"socent","title":"#socent"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 251040, 1, '2021-09-15T20:42:26Z', '2021-09-22T16:31:24Z', '2021-09-15T20:42:26Z')
