INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Dubs invited to ‘Festival of Fundraising’ starting Sept 20', 'dubs-zoomed-in-to-fundraising', '<p>A ‘Festival of Fundraising’ opens in Dublin, on September 20<sup>th</sup>. It is aimed at members of groups that are involved in Dublin City Public Participation Network (PPN).</p>
<p>The “festival” will run for four days from September 20-23 with all events held on Zoom and all free for PPN members, including workshops, training sessions, networking opportunities and one-to-one mentoring.</p>
<p>The workshops have eye-catching titles &#8211; from ‘Ask Me Anything about fundraising’ to ‘100 Days to Christmas – How to maximize your fundraising this Christmas’.</p>
<p>Thinking ahead, Dublin PPN offered Zoom familiarisation classes to anybody wishing to attend but unsure of how to use the Zoom app. They recommended people check in with the neighbouring PPN in Dun Laoghaire-Rathdown which runs ‘Zoom Training for Beginners’ classes.</p>
<p>“The Festival of Fundraising is an opportunity to connect with colleagues, from other organisations in the PPN throughout Dublin City, and to grow your fundraising knowledge, capacity and network,” say the organisers.</p>
<p>It is being delivered in collaboration with Academy Street Workshop.</p>
<p><strong>Find out more, see the programme and register here:</strong> <a href="https://dublincityppn.ie/ppn-bulletin-festival-of-fundraising/">https://dublincityppn.ie/ppn-bulletin-festival-of-fundraising/</a></p>
<p><em>* On Sept 16th the original text here was updated.</em></p>', 'A ‘Festival of Fundraising’ opens in Dublin, on September 20th. It is aimed at members of groups that are involved in Dublin City Public Participation Network (PPN).', 'https://changingireland.ie/wp-content/uploads/2021/09/Dublin-City-PPNs-Festival-of-Fundraising.png', '', '[{"slug":"funding","title":"Funding"}]', '[{"slug":"fundraising","title":"fundraising"}]', '', 251036, 1, '2021-09-15T12:51:15Z', '2021-09-22T16:32:45Z', '2021-09-15T12:51:15Z')
