INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Dr Mike Ryan of WHO and Minister Joe O’Brien for community conference', 'dr-mike-ryan-of-who-and-minister-joe-obrien-meet-at-community-conference', '<p>Dr. Ryan, the executive director of the WHO’s Health Emergencies Programme and Minister O’Brien will take part in a discussion chaired by CWI chairperson Ronnie Fay.</p>
<p>The conference is titled ‘Not Just Recovery?’ and it will, said organisers, “provide an opportunity for reflection on the experience of the most disadvantaged communities in Ireland and globally during the past 18 months, the lessons learned, and the key priorities for action in building a just and sustainable recovery as we emerge from the Covid-19 crisis”.</p>
<p>Registration for attendance closed on September 15, though it is expected the proceedings will be recorded.</p>
<p>The CWI (<a href="https://www.cwi.ie">https://www.cwi.ie</a>) is supported by the Department of Rural and Community Development’s Support Scheme for National Organisations.</p>
<h2>WORKSHOP THEMES</h2>
<p>The workshop themes for the event are:</p>
<p>1. Racism and Addressing the Rise of the Far-Right.</p>
<p>2. Climate and a Just Transition.</p>
<p>3. Health.</p>
<p>4. Civil Rights and Civil Liberties.</p>
<p>5. Women’s Rights.</p>
<p>6. Social Dialogue and Participation in Decision Making.</p>
<p>7. Building an All-Island approach.</p>', 'Dr. Mike Ryan of the World Health Organisation (WHO) and Joe O’Brien, Minister of State for Rural and Community Development are lined up to take part in this year’s Community Work Ireland conference. It is scheduled to take place (online) on September 28th.', 'https://changingireland.ie/wp-content/uploads/2021/09/Dr-Mike-Ryan-of-W.H.O.-and-Minister-Joe-OBrien.png', '', '[{"slug":"climate-justice","title":"Climate Justice"}]', '[{"slug":"communityaction","title":"#CommunityAction"}]', '', 251033, 1, '2021-09-15T11:54:22Z', '2021-09-16T09:19:24Z', '2021-09-15T11:54:22Z')
