INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Islands embrace remote working – but need more hubs & houses', 'islands-embrace-remote-working-but-need-more-hubs-houses', '<p><span>B</span>ack in 2019 Irena Meilick and her husband Bruno decided to move from Germany to the Irish countryside because they are nature lovers.</p>
<p>   The couple had three young children at the time and were looking for somewhere to settle by the sea, “with fresh air and nature around us,” she says.</p>
<p>   Her husband is a web programmer so he can work from anywhere. Ms. Meilick started looking on Daft.ie and one day she spotted a small house to rent on Inishturk, she says.</p>
<p>   Within weeks they viewed it and “instantly fell in love with the little house,” she says. “It has very nice views.”</p>
<p>   They moved in with just the belongings they had brought in their backpacks and didn’t go back to Germany to get the rest of their stuff for a year, she says.</p>
<p>   Island life is everything they dreamed it would be and more. “We love it, it’s even better than we thought it would be,” she says.</p>
<figure aria-describedby="caption-attachment-250830"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-1024x602.png" alt="" width="1024" height="602" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-1024x602.png 1024w, https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-300x176.png 300w, https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-768x451.png 768w, https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-1536x902.png 1536w, https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM-1080x635.png 1080w, https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.43.10-PM.png 1542w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption><em>• Bruno and Irena Meilick and family found life on Inishturk “even better than we thought it would be”.</em></figcaption></figure>
<p>   They never imagined that the small community would be so welcoming to them. “It is such a community,” she says. “They were so welcoming from the beginning.”</p>
<h2><span lang="EN-GB">Remote Working</span></h2>
<p align="left"><span lang="EN-GB">   Since the pandemic struck, the increase in remote working has presented a glimmer of hope to young islanders from Inishturk and people who dreamed of moving home to enjoy island life have found a way. </span></p>
<p align="left"><span lang="EN-GB">   Unemployment and emigration have always been high on the list of challenges faced by Ireland’s offshore islands, says </span><b><span lang="EN-GB">Mary O’Toole, co-ordinator of Inishturk Development Company.</span></b></p>
<p align="left"><span lang="EN-GB">   But, increasingly companies are open to employing people to work remotely. Advances in technology could open up a wide variety of jobs and slow the flow of young people to the mainland and beyond, to look for work. </span></p>
<p align="left"><span lang="EN-GB">   “We are looking at developing a digital hub on the island,” says Ms O’Toole. “Which will not only ensure connectivity with the excellent broadband we have &#8211; but will see the return of islanders hopefully.”</span></p>
<p align="left"><span lang="EN-GB">   While islanders face challenges of employment and construction costs, they are benefiting from improved amenities too, she says. </span></p>
<p align="left"><b><span lang="EN-GB">   Máire Ui Mhaoláin, CEO of Comhar na nOileán,</span></b><span lang="EN-GB"> says that there are plans for digital hubs in many islands and remote working is improving the range of employment available to islanders across the offshore islands. </span></p>
<p align="left"><span lang="EN-GB">   Ms. Meilick says her husband is remote working as a self-employed web programmer and has no issues with the internet.</span></p>
<p align="left"><span lang="EN-GB">   She has started working in the community garden and helps out in the shop and the restaurant too, she says.</span></p>
<h2><span lang="EN-GB">Changes on Inishturk</span></h2>
<p align="left"><span lang="EN-GB">   Around 18 years ago Changing Ireland reported that people living on Inishturk had to travel to the mainland for a haircut. </span></p>
<p align="left"><span lang="EN-GB">   That is still the case, says Ms O’Toole, but there are more regular sailings nowadays. </span></p>
<p align="left"><span lang="EN-GB">   An extension to the pier in 2006 means that the boat now runs in all weather, she says. There is a daily service from Roonagh and a service from Cleggan twice a week.</span></p>
<figure aria-describedby="caption-attachment-250832"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-1024x683.jpeg" alt="" width="1024" height="683" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-1024x683.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-300x200.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-768x512.jpeg 768w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-1536x1024.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7-1080x720.jpeg 1080w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-7.jpeg 2048w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption><em>• Inishturk Island. Source: Inishturk Facebook page.</em></figcaption></figure>
<p align="left"><span lang="EN-GB">   “We have advanced a lot in the last 18 years,” she says.<br />
In 2003, Inishturk got a new health centre and they have a nurse available there full time and a GP visits once every three weeks, says Ms O’Toole.<br />
If the doctor’s visit is urgent people travel to the mainland, she says.<br />
The coast guard and the RNLI provide back up to the nurse and have been assisting with the vaccination programme, “The service of the coast guard and the RNLI has been just absolutely amazing,” she says.</span></p>
<h2><span lang="EN-GB">Restaurant</span></h2>
<p>An extension to the community club, which now includes a restaurant and function room, has opened up the possibility of going out for a meal.</p>
<p>“The restaurant is a massive addition,” she says. It is open seasonally and is well used by locals.</p>
<p>The sports pitch was upgraded in 2010, and dressing rooms built in 2012. That has allowed Inishturk to host matches and clubs have travelled from the mainland to play.</p>
<h2><span lang="EN-GB">Building a Sustainable Future</span></h2>
<figure aria-describedby="caption-attachment-250839"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-5.jpeg" alt="" width="855" height="315" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-5.jpeg 855w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-5-300x111.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-5-768x283.jpeg 768w" sizes="(max-width: 855px) 100vw, 855px" /><figcaption><em>•  Inishturk by boat. Source: Inishturk Facebook page.</em></figcaption></figure>
<p>The population of the Inishturk is 62 and there are just five children in the primary school.</p>
<p>“We have a wonderful, vibrant school with two teachers, says Ms. O’ Toole. “The children get plenty of special attention.”</p>
<p>The primary school got a boost when Ms Meilick’s family and another family also from Germany, moved to the island.</p>
<p>Ms. Meilick’s eldest child, aged 9, is in the local school. “The school is such a nice place, the teacher is great,”she say. “He has the smallest class ever.”</p>
<p>She is homeschooling her 7-year-old for now. One of the things that attracted the couple to Ireland was being able to let their children choose between going to school.</p>
<p>Homeschooling is very complicated in Germany, she says.</p>
<p>Secondary students travel to the mainland and board during the week, says Ms O’Toole. “That is all part and parcel of island life. We are still dealing with population decline which is ongoing for any rural community.”</p>
<figure aria-describedby="caption-attachment-250838"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11.jpeg" alt="" width="719" height="719" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11.jpeg 719w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-300x300.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-150x150.jpeg 150w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-440x440.jpeg 440w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-24x24.jpeg 24w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-48x48.jpeg 48w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-11-96x96.jpeg 96w" sizes="(max-width: 719px) 100vw, 719px" /><figcaption><em>• A friendly visitor to Inishturk. Source: Inishturk Facebook page.</em></figcaption></figure>
<p>There is some employment on the island including farming and fishing, she says. And publicly funded jobs too &#8211; like herself and her colleagues, the teachers and the nurse.</p>
<p>There is work too in tourism, which is seasonal, yet many young people still have to go to the mainland for work.</p>
<p>With plans for a digital hub on the island though that could be set to change, offering hope to islanders that wasn’t there before.</p>
<p>Since Covid-19 restrictions kicked in four islanders have come home. They are working remotely for companies based in Denmark, the UK and two on the mainland, she says.</p>
<p>“This is a massive shift in the right direction. It is our goal to increase this number and capitalise on this opportunity,” says Ms O’Toole.</p>
<p>Companies are finding that “remote working is working,” she says.</p>
<p>Those islanders who have come home are benefitting from the change in approach. “They are content doing it and they are happy to be home while still working away.”</p>
<p>Getting the digital hub up and running as soon as possible is a key priority for the sustainability of Inishturk, she says.</p>
<p>Another major issue is construction costs, it can be around 30 percent more expensive to build a house on the island. Materials have to be shipped out and tradesmen have to be accommodated in B&amp;Bs too.</p>
<p>She says that if both of those issues could be tackled, it would make it easier for people to move to Inishturk and for young people to stay living on the island too.</p>
<p>“Sustaining the population and ensuring that Inishturk has a bright and vibrant future for many years to come,” says Ms. O’Toole.</p>
<p>“Of course we would love to see more families here,” says Ms Meilick, “it is so important for the community.”</p>
<figure aria-describedby="caption-attachment-250840"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-4.jpeg" alt="" width="960" height="540" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-4.jpeg 960w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-4-300x169.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-4-768x432.jpeg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption><em>• A rainbow sighting on the island. Source: Inishturk Facebook Page.</em></figcaption></figure>
<p>&nbsp;</p>
<figure aria-describedby="caption-attachment-250841"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10.jpeg" alt="" width="960" height="960" srcset="https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10.jpeg 960w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-300x300.jpeg 300w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-150x150.jpeg 150w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-768x768.jpeg 768w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-440x440.jpeg 440w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-24x24.jpeg 24w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-48x48.jpeg 48w, https://changingireland.ie/wp-content/uploads/2021/07/Inish-Turk-10-96x96.jpeg 96w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption><em>• Sunset on the island. Source: Inishturk Facebook page.</em></figcaption></figure>', 'Remote working in the extreme: From Germany to Inishturk, Co. Mayo', 'https://changingireland.ie/wp-content/uploads/2021/07/Screen-Shot-2021-07-22-at-7.42.34-PM.png', '', '[{"slug":"development-work","title":"Development Work"}]', '[{"slug":"islands","title":"Islands"},{"slug":"remote-work","title":"Remote Work"}]', '', 250827, 1, '2021-07-22T18:51:26Z', '2023-07-04T17:40:28Z', '2021-07-22T18:51:26Z')
