INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Show your colours on #IDAHOBIT Day & LGBTI+ Awareness Week (May 16-22)', 'show-your-colours-on-idahobit-day-lgbti-awareness-week-may-16-22', '<p>For example, in Cork, the city&#8217;s LGBT Inter-Agency Group said, “Cork will mark international IDAHOBIT this year as it has every year this past decade by bringing the City Council, public services, community groups and lgbti+ NGOs together.”</p>
<p>The inter-agency group is a member of the Rainbow Cities Network and has submitted an entry for the network’s photography exhibition focusing on “intersectionality in the LGBTQ Community”.</p>
<p>“Annually we raise the Rainbow Flag over the city and across public buildings, parks and community spaces. This year, we will raise the Intersectional Rainbow Flag, because as Audre Lorde once memorably said, “There is no such thing as a single issue struggle, because we do not live single issue lives.”</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-1024x683.jpg" alt="" width="1024" height="683" srcset="https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City-1080x720.jpg 1080w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-City-is-a-Rainbow-City.jpg 1720w" sizes="(max-width: 1024px) 100vw, 1024px" /></p>
<p>Already,<span> the nursing staff at Mercy University Hospital, Cork, led by director of nursing Margaret McKiernan, who is a  a member of the Cork LGBTI+ InterAgency Group, are leading the way. </span></p>
<p><span>This  year’s theme from the Irish Nurses Organisation is &#8216;A Voice to Lead&#8217; and the Mercy Hospital staff are campaigning for a healthcare system that recognises the uniqueness and diversity of every one they encounter and the interconnectedness of us all.</span></p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-1024x677.jpg" alt="" width="1024" height="677" srcset="https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-1024x677.jpg 1024w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-300x198.jpg 300w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-768x508.jpg 768w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-1536x1016.jpg 1536w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020-1080x714.jpg 1080w, https://changingireland.ie/wp-content/uploads/2021/05/Cork-RCN-May-2020.jpg 1597w" sizes="(max-width: 1024px) 100vw, 1024px" /></p>
<p><span>Keep up to date with the latest events during the week.<br />
</span></p>
<p>Twitter: <a href="https://twitter.com/corklgbtweek">@CorkLGBTWeek</a><br />
Also on <a href="https://www.facebook.com/CorkLgbtAwarenessWeek?fref=ts">Facebook</a>.</p>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-1024x390.jpg" alt="" width="1024" height="390" srcset="https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-1024x390.jpg 1024w, https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-300x114.jpg 300w, https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-768x292.jpg 768w, https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-1536x585.jpg 1536w, https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo-1080x411.jpg 1080w, https://changingireland.ie/wp-content/uploads/2021/05/2021-Cork-LGBTI-logo.jpg 1708w" sizes="(max-width: 1024px) 100vw, 1024px" /></p>', 'IDAHOBIT stands for International Day Against Homophobia, Biphobia, Intersexism and Transphobia and it takes place on May 17th, in the midst of LGBTI+ Awareness Week (May 16-22). Events are to take place around the country.', 'https://changingireland.ie/wp-content/uploads/2021/05/186374671_4129984343727081_1523513397913572768_n.jpg', '', '[{"slug":"equality-rights","title":"Equality & Rights"}]', '[]', '', 250579, 1, '2021-05-13T19:52:00Z', '2021-05-13T19:53:08Z', '2021-05-13T19:52:00Z')
